create function private.member(p uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.project_members where project_id=p and user_id=auth.uid() and is_active) $$;
create function private.role(p uuid, roles public.project_role[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.project_members where project_id=p and user_id=auth.uid() and is_active and role=any(roles)) $$;
grant usage on schema private to authenticated;
grant execute on function private.member(uuid),private.role(uuid,public.project_role[]) to authenticated;
create function private.finance(p uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.role(p,array['OWNER','ADMIN','FINANCE_MANAGER']::public.project_role[]) $$;
create function private.assert_finance(p uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not private.finance(p) then raise exception 'PERMISSION_DENIED'; end if; end $$;
create function private.log(p uuid, action text, entity text, eid uuid, reason text default null) returns void language plpgsql security definer set search_path='' as $$ begin insert into public.audit_logs(project_id,actor_user_id,action,entity_type,entity_id,reason) values(p,auth.uid(),action,entity,eid,reason); insert into public.activity_events(project_id,actor_user_id,type,entity_type,entity_id,summary) values(p,auth.uid(),action,entity,eid,replace(action,'_',' ')); end $$;
create function private.freeze_ledger() returns trigger language plpgsql set search_path='' as $$ begin raise exception 'LEDGER_IMMUTABLE'; end $$;
create trigger immutable_ledger before update or delete on public.ledger_entries for each row execute function private.freeze_ledger();
create function private.balance_event() returns trigger language plpgsql set search_path='' as $$ declare s numeric; begin select coalesce(sum(case when direction='DEBIT' then amount_minor::numeric else -amount_minor::numeric end),0) into s from public.ledger_entries where financial_event_id=new.financial_event_id; if s<>0 then raise exception 'UNBALANCED_EVENT'; end if; return null; end $$;
create constraint trigger balanced_ledger after insert on public.ledger_entries deferrable initially deferred for each row execute function private.balance_event();
create function private.freeze_event() returns trigger language plpgsql set search_path='' as $$ begin if tg_op='DELETE' or (to_jsonb(new)-'status')<>(to_jsonb(old)-'status') or new.status<>'REVERSED' or old.status<>'POSTED' then raise exception 'POSTED_EVENT_IMMUTABLE'; end if; if not exists(select 1 from public.financial_events where reverses_event_id=old.id) then raise exception 'REVERSAL_REQUIRED'; end if; return new; end $$;
create trigger immutable_event before update or delete on public.financial_events for each row execute function private.freeze_event();
create function private.profile_created() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,email,full_name,avatar_url) values(new.id,coalesce(new.email,''),coalesce(new.raw_user_meta_data->>'full_name',''),new.raw_user_meta_data->>'avatar_url') on conflict(id) do update set email=excluded.email; return new; end $$;
create trigger auth_profile after insert or update of email on auth.users for each row execute function private.profile_created();
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or exists(select 1 from public.project_members m where m.user_id=profiles.id and m.is_active and private.member(m.project_id)));
create policy profiles_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
grant update(full_name,locale,timezone,avatar_url) on public.profiles to authenticated;
create policy project_read on public.projects for select to authenticated using(private.member(id));
do $$ declare t text; begin for t in select tablename from pg_tables where schemaname='public' and tablename not in ('profiles','projects','notifications','document_templates','audit_logs') loop execute format('create policy member_read on public.%I for select to authenticated using(private.member(project_id))',t); end loop; end $$;
create policy audit_read on public.audit_logs for select to authenticated using(private.finance(project_id));
create policy notification_read on public.notifications for select to authenticated using(user_id=auth.uid());
create policy notification_update on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
grant update(read_at) on public.notifications to authenticated;
create policy template_read on public.document_templates for select to authenticated using(project_id is null or private.member(project_id));
grant select on all tables in schema public to authenticated;
revoke execute on all functions in schema private from public;
grant execute on function private.member(uuid),private.role(uuid,public.project_role[]),private.finance(uuid) to authenticated;
create function private.account(p uuid, kind text, owner_id uuid default null) returns uuid language plpgsql security definer set search_path='' as $$ declare a uuid; begin select id into a from public.financial_accounts where project_id=p and account_type=kind and owner_user_id is not distinct from owner_id limit 1; if a is null then insert into public.financial_accounts(project_id,name,account_type,owner_user_id,currency) select p,replace(kind,'_',' ')||coalesce(' '||owner_id::text,''),kind,owner_id,currency from public.projects where id=p returning id into a; end if; return a; end $$;
create function private.entry(p uuid,e uuid,a uuid,d text,n bigint,cat uuid default null) returns void language plpgsql set search_path='' as $$ begin if n<=0 then raise exception 'INVALID_AMOUNT'; end if; insert into public.ledger_entries(project_id,financial_event_id,account_id,direction,amount_minor,currency,category_id) select p,e,a,d,n,currency,cat from public.projects where id=p; end $$;
create function private.account_balance(a uuid) returns bigint language sql stable set search_path='' as $$ select coalesce(sum(case when direction='DEBIT' then amount_minor else -amount_minor end),0)::bigint from public.ledger_entries where account_id=a $$;
create function private.source_outstanding(a uuid) returns bigint language sql stable set search_path='' as $$ select coalesce((select amount_minor from public.purchase_funding_allocations where id=a),0)-coalesce((select sum(s.amount_minor) from public.settlement_allocations s join public.financial_events e on e.id=s.event_id where s.source_allocation_id=a and s.kind in ('PAYMENT','REFUND','NONREIMBURSABLE') and e.status='POSTED'),0) $$;
create function public.create_project(p_name text,p_code text,p_currency text default 'INR',p_opening text default '0') returns uuid language plpgsql security definer set search_path='' as $$ declare p uuid; e uuid; a uuid; f uuid:=gen_random_uuid(); n bigint:=p_opening::bigint; begin if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if; if length(trim(p_name))<2 or length(trim(p_code))<2 or n<0 then raise exception 'INVALID_PROJECT'; end if; insert into public.projects(name,code,currency,created_by) values(trim(p_name),trim(p_code),p_currency,auth.uid()) returning id into p; insert into public.project_members(project_id,user_id,role) values(p,auth.uid(),'OWNER'); a:=private.account(p,'BANK'); perform private.account(p,'EXPENSE'); perform private.account(p,'FUNDING'); perform private.account(p,'VENDOR_PAYABLE'); insert into public.categories(project_id,name) select p,unnest(array['Electronics','Mechanical','Travel','Registration','Reserve','Other']); if n>0 then insert into public.financial_events(project_id,event_type,description,created_by,posted_by,source_id,idempotency_key,command_hash) values(p,'FUNDING','Opening Balance',auth.uid(),auth.uid(),f,gen_random_uuid(),'opening') returning id into e; perform private.entry(p,e,a,'DEBIT',n); perform private.entry(p,e,private.account(p,'FUNDING'),'CREDIT',n); insert into public.funding_sources(id,project_id,name,type,currency) values(f,p,'Opening Balance','opening_balance',p_currency); insert into public.funding_tranches(project_id,funding_source_id,financial_event_id,amount_minor,received_at) values(p,f,e,n,current_date); end if; perform private.log(p,'project_created','projects',p); return p; end $$;
create function public.invite_member(p_project uuid,p_email text,p_role public.project_role) returns text language plpgsql security definer set search_path='' as $$ declare token text:=encode(extensions.gen_random_bytes(32),'hex'); i uuid; begin if not private.role(p_project,array['OWNER','ADMIN']::public.project_role[]) or p_role='OWNER' or (p_role='ADMIN' and not private.role(p_project,array['OWNER']::public.project_role[])) then raise exception 'PERMISSION_DENIED'; end if; if p_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then raise exception 'INVALID_EMAIL'; end if; insert into public.project_invites(project_id,email,role,token_hash,expires_at,invited_by) values(p_project,lower(trim(p_email)),p_role,encode(extensions.digest(token,'sha256'),'hex'),now()+interval '7 days',auth.uid()) returning id into i; perform private.log(p_project,'member_invited','project_invites',i); return token; end $$;
create function public.accept_invite(p_token text) returns uuid language plpgsql security definer set search_path='' as $$ declare i public.project_invites; em text; begin select email into em from auth.users where id=auth.uid() and email_confirmed_at is not null; select * into i from public.project_invites where token_hash=encode(extensions.digest(p_token,'sha256'),'hex') for update; if i.id is null or i.accepted_at is not null or i.revoked_at is not null or i.expires_at<now() or lower(em) is distinct from i.email then raise exception 'INVITE_INVALID'; end if; insert into public.project_members(project_id,user_id,role) values(i.project_id,auth.uid(),i.role) on conflict(project_id,user_id) do nothing; update public.project_invites set accepted_at=now() where id=i.id; perform private.log(i.project_id,'member_joined','project_members',auth.uid()); return i.project_id; end $$;
create function public.change_member(p_project uuid,p_user uuid,p_role public.project_role,p_active boolean default true) returns void language plpgsql security definer set search_path='' as $$ declare old_role public.project_role; begin perform 1 from public.projects where id=p_project for update; select role into old_role from public.project_members where project_id=p_project and user_id=p_user; if not private.role(p_project,array['OWNER','ADMIN']::public.project_role[]) or ((old_role='OWNER' or p_role in ('OWNER','ADMIN')) and not private.role(p_project,array['OWNER']::public.project_role[])) then raise exception 'PERMISSION_DENIED'; end if; if old_role='OWNER' and (p_role<>'OWNER' or not p_active) and (select count(*) from public.project_members where project_id=p_project and role='OWNER' and is_active)=1 then raise exception 'SOLE_OWNER'; end if; update public.project_members set role=p_role,is_active=p_active where project_id=p_project and user_id=p_user; perform private.log(p_project,'membership_changed','project_members',p_user); end $$;
create function public.transfer_owner(p_project uuid,p_user uuid) returns void language plpgsql security definer set search_path='' as $$ begin perform 1 from public.projects where id=p_project for update; if not private.role(p_project,array['OWNER']::public.project_role[]) or not exists(select 1 from public.project_members where project_id=p_project and user_id=p_user and is_active) then raise exception 'PERMISSION_DENIED'; end if; update public.project_members set role='OWNER' where project_id=p_project and user_id=p_user; update public.project_members set role='ADMIN' where project_id=p_project and user_id=auth.uid() and user_id<>p_user; perform private.log(p_project,'owner_transferred','projects',p_project); end $$;
revoke execute on all functions in schema public from public;
grant execute on function public.create_project(text,text,text,text),public.invite_member(uuid,text,public.project_role),public.accept_invite(text),public.change_member(uuid,uuid,public.project_role,boolean),public.transfer_owner(uuid,uuid) to authenticated;
